// Коллекция опубликована, но без баннеров - на витрине будет пустая шапка.
const c = $input.first().json.data.collection;
const нет = [];
if (!c.square || !c.square.value) нет.push('banner_square');
if (!c.wide || !c.wide.value) нет.push('banner_wide');

const опубликована = c.resourcePublicationsCount.count > 1;

return [{ json: {
  handle: c.handle,
  title: c.title,
  товаров: c.productsCount.count,
  опубликована,
  нет_баннеров: нет,
  требует_внимания: опубликована && нет.length > 0,
} }];
